for (int x = 1; x <= 10; x++) {
    for (int y = 1; y <= 10; y++) {
        System.out.print(x * y + "\t");
    }
    System.out.println();
}

char flag = 'y';
while (flag != 'n') {
    System.out.print("Enter a range greater than 0: ");
    int range = console.nextInt();
    if (range > 0) {
        for (int i = 1; i <= range; i++) {
            System.out.print(i + ", ");
        }
    } else {
        System.out.println("Invalid number. Try again!");
        continue;
    }
    System.out.print("\nRepeat? (y/n): ");
    flag = console.next().charAt(0);
}
